  function action(name,data={}) { if(isMobileSingle() && ['dashboard','history','focus','import','zoom-in','zoom-out','panel-expand','panel-minimize','panel-restore','add-scene','edit-scene','delete','split','screenwrite','export','open-chat','mobile-nav'].includes(name)) return toast('This phone is in single-generation mode. Open Dominion on desktop for saved projects and editing.','error'); switch(name) { case 'close': close(); break; case 'dashboard': dashboard(); break; case 'history': historyDialog();break; case 'focus': mutate(state.focus?'Exited editor focus':'Entered editor focus',()=>state.focus=!state.focus); break; case 'undo': undo(); break; case 'redo': redo(); break; case 'play': {const video=$('#dv-preview-video',root);if(video){if(video.paused){video.play().catch(()=>{});state.playing=true;}else{video.pause();state.playing=false;}const b=$('[data-action="play"]',root);if(b)b.textContent=state.playing?'❚❚':'▶';}else toast('Select a generated video clip first.');break;} case 'import': $('#dv-import',root)?.click(); break; case 'zoom-in': state.zoom=Math.min(3,state.zoom+.25); checkpoint('Changed timeline zoom');render(); break; case 'zoom-out': state.zoom=Math.max(.5,state.zoom-.25); checkpoint('Changed timeline zoom');render(); break; case 'panel-expand': panel(data.panel,state.panels[data.panel]==='expanded'?'regular':'expanded'); break; case 'panel-minimize': panel(data.panel,'minimized'); break; case 'panel-restore': panel(data.panel,'regular'); break; case 'add-scene': addScene(); break; case 'edit-scene': editScene(data.sceneId); break; case 'delete': deleteSelected(); break; case 'split': splitSelected(); break; case 'generate': generate(); break; case 'screenwrite': screenwrite(); break; case 'export': exportProject(); break; case 'open-chat': $('#dv-chat-input',root)?.focus(); break; case 'mobile-nav': mobileNav(); break; } }
