  async function importMedia(files){if(isMobileSingle())return toast('Import is available when a desktop session is running.','error');if(!files.length)return;try{await ensureProject();for(const file of files){toast(`Importing and verifying ${file.name}…`);const res=await fetch(`${API}/uploads?projectId=${encodeURIComponent(state.project.id)}&filename=${encodeURIComponent(file.name)}`,{method:'POST',credentials:'same-origin',headers:{'Content-Type':file.type||'application/octet-stream','X-Dominion-Device':device(),'X-Dominion-Filename':file.name},body:file});let data;try{data=await res.json();}catch{data=null;}if(!res.ok)throw new Error(typeof data?.error==='string'?data.error:data?.error?.message||`Import failed with ${res.status}.`);const start=state.clips.reduce((max,clip)=>Math.max(max,clip.start+clip.duration),0),duration=Math.max(.1,Number(data.duration)||1),videoId=uid();if(data.hasVideo)state.clips.push({id:videoId,trackId:'v1',name:file.name,start,duration,sourceStart:0,type:'video',linked:null,mediaFile:data.filename,src:data.mediaUrl,volume:1,fit:'contain'});if(data.hasAudio){const audioId=uid(),video=state.clips.find(c=>c.id===videoId);state.clips.push({id:audioId,trackId:'a1',name:`${file.name} audio`,start,duration,sourceStart:0,type:'audio',linked:data.hasVideo?videoId:null,mediaFile:data.filename,src:data.mediaUrl,volume:1});if(video)video.linked=audioId;}state.selected=data.hasVideo?videoId:state.clips.at(-1)?.id;await checkpoint(`Imported ${file.name}`);render();}toast('Imported media is verified and ready to edit.');}catch(error){render();toast(readable(error),'error');}}
