  function mergeServerClips(serverClips, jobId, mediaUrl) { const incoming=serverClips.filter(c=>c&&['video','audio'].includes(c.type)).map(c=>({...clone(c),id:String(c.id||uid()),mediaJobId:c.mediaJobId||jobId,src:c.src||mediaUrl||null,sourceStart:Number(c.sourceStart||0),duration:Number(c.duration||0)})).filter(c=>c.duration>0); if(!incoming.length)return 0; const before=clone(projectPayload()); for(const clip of incoming){const match=state.clips.find(existing=>(existing.id===clip.id)||(existing.type===clip.type&&existing.mediaJobId===clip.mediaJobId)); if(match)Object.assign(match,clip);else state.clips.push(clip);} checkpoint(`Synced verified generated ${incoming.length===1?'clip':'clips'}`,before); render(); return incoming.length; }
