  async function screenwrite(){if(!fullEditor())return toast('Screenwriting is available on desktop.','error');if(state.inflight.screenwriter)return toast('The screenwriter is already working.','error');const prompt=$('#dv-script',root)?.value.trim();if(!prompt)return toast('Add a story brief first.');const tokens=tokenEstimate(prompt);if(tokens>115000)return toast('Screenplay text is limited to 115,000 tokens.','error');state.inflight.screenwriter=true;render();try{await ensureProject();toast('Screenwriter is preparing the next saved section…');const d=await request('/screenwrite',{method:'POST',body:JSON.stringify({projectId:state.project.id,prompt,limit:115000})});if(d.text)state.screenplay=d.text;await checkpoint('Saved screenplay section');toast('Screenplay checkpoint saved.');}catch(error){toast(readable(error),'error');}finally{state.inflight.screenwriter=false;render();}}
